//! Network administration (design §2.6): blocking calls for the admin job
//! threads, never the application thread. Every method defaults to
//! "unsupported" ([`CoordError::Unsupported`], `None` or empty
//! diagnostics).
//!
//! Where the design leaves fields open, the data types mirror today's
//! `hub_ncp` (`lifecycle`, `netops`, `fw`) and zigbee-zrhp types as neutral
//! copies; the ZRHP adapter maps them (PR E/G).

use std::io;
use std::time::Duration;

use crate::{CoordError, CoordStatus, NetworkParams};

/// Network formation parameters; `None` fields are generated by the
/// backend (random PAN ID, EPID and key).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct FormParams {
    /// Channel mask (the NCP picks the quietest channel).
    pub channel_mask: u32,
    /// PAN ID.
    pub pan_id: Option<u16>,
    /// Extended PAN ID (wire order).
    pub ext_pan_id: Option<[u8; 8]>,
    /// Network key.
    pub network_key: Option<[u8; 16]>,
    /// TX power (dBm).
    pub tx_power: i8,
}

impl Default for FormParams {
    fn default() -> Self {
        Self {
            channel_mask: 0x07FF_F800,
            pan_id: None,
            ext_pan_id: None,
            network_key: None,
            tx_power: 0,
        }
    }
}

/// One channel of an energy scan.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct EnergyChannel {
    /// Channel (11–26).
    pub channel: u8,
    /// Highest RSSI seen, dBm (antenna-referred).
    pub max_rssi_dbm: i8,
    /// Energy (0–255, ED scale).
    pub energy: u8,
}

/// One beacon of an active scan.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Beacon {
    /// Channel.
    pub channel: u8,
    /// PAN ID.
    pub pan_id: u16,
    /// Extended PAN ID (wire order).
    pub ext_pan_id: [u8; 8],
    /// Short address of the sender.
    pub src: u16,
    /// LQI.
    pub lqi: u8,
    /// RSSI.
    pub rssi: i8,
    /// The sender permits joining.
    pub permit_join: bool,
    /// Stack profile.
    pub stack_profile: u8,
    /// NWK update ID.
    pub update_id: u8,
}

/// A completed channel change.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ChannelChange {
    /// The channel the radio is on (the old one if the change failed).
    pub channel: u8,
    /// NWK update ID now in use.
    pub nwk_update_id: u8,
}

/// One neighbor of the coordinator.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Neighbor {
    /// IEEE (wire order).
    pub ieee: [u8; 8],
    /// Short address.
    pub nwk: u16,
    /// 0 coordinator, 1 router, 2 end device.
    pub device_type: u8,
    /// Receiver on when idle.
    pub rx_on: bool,
    /// 0 parent, 1 child, 2 sibling, 3 none, 4 previous child.
    pub relationship: u8,
    /// LQI.
    pub lqi: u8,
    /// Outgoing link cost.
    pub outgoing_cost: u8,
    /// Age.
    pub age: u8,
}

/// One route of the coordinator.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Route {
    /// Destination.
    pub dst: u16,
    /// Next hop.
    pub next_hop: u16,
    /// Route status.
    pub status: u8,
    /// Route flags.
    pub flags: u8,
}

/// One child of the coordinator.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Child {
    /// IEEE (wire order).
    pub ieee: [u8; 8],
    /// Short address.
    pub nwk: u16,
    /// MAC capability.
    pub capability: u8,
    /// End device timeout index.
    pub timeout_exp: u8,
    /// Time since the last poll (ms).
    pub last_poll_ms: u32,
}

/// The coordinator's own tables, each read on its own.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TablesRead {
    /// Neighbor table.
    pub neighbors: Result<Vec<Neighbor>, CoordError>,
    /// Child table.
    pub children: Result<Vec<Child>, CoordError>,
    /// Route table, when requested.
    pub routes: Option<Result<Vec<Route>, CoordError>>,
}

/// One diagnostic counter.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct DiagCounter {
    /// Backend counter ID.
    pub id: u16,
    /// Counter group.
    pub group: &'static str,
    /// Counter name, if the backend knows it.
    pub name: Option<&'static str>,
    /// Value.
    pub value: u32,
}

/// NCP runtime status (ZRHP `SYS_GET_STATUS`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct NcpStatus {
    /// Network state (0 none, 1 formed-down, 2 up).
    pub network_state: u8,
    /// Uptime (s).
    pub uptime_s: u32,
    /// Free APS slots.
    pub free_aps_slots: u16,
    /// Host-absent queue depth.
    pub host_absent_queue: u16,
    /// Dirty writebacks.
    pub dirty_writebacks: u16,
    /// A restore is in progress.
    pub restore_in_progress: bool,
    /// Key export is locked.
    pub key_export_locked: bool,
    /// Paging is active.
    pub paging_active: bool,
    /// PTA coexistence is enabled.
    pub pta_coex: bool,
    /// GP commissioning is open.
    pub gp_commissioning: bool,
    /// Joining is permitted.
    pub permit_join: bool,
}

/// Security frame counters of the NCP.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct FrameCounters {
    /// NWK current.
    pub nwk: u32,
    /// NWK durable limit.
    pub nwk_limit: u32,
    /// APS current.
    pub aps: u32,
    /// APS durable limit.
    pub aps_limit: u32,
    /// Reservation stride.
    pub stride: u32,
}

/// NCP diagnostics; the application renders the JSON.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Diagnostics {
    /// Runtime status.
    pub status: Option<NcpStatus>,
    /// NCP counters.
    pub counters: Vec<DiagCounter>,
    /// Frame counters.
    pub frame_counters: Option<FrameCounters>,
    /// Host-side link counters.
    pub host_link: Vec<DiagCounter>,
    /// The NCP supports Wi-Fi coexistence (PTA).
    pub coex: bool,
    /// TX power the operator set (dBm).
    pub tx_power_set: Option<i8>,
    /// Requests the NCP does not implement.
    pub unsupported: Vec<&'static str>,
    /// Other failures, one line each.
    pub errors: Vec<String>,
}

/// The `DEVICE` child info of a backup.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BackupChild {
    /// MAC capability.
    pub capability: u8,
    /// End device timeout index.
    pub timeout_exp: u8,
}

/// A device's link key in a backup.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BackupLinkKey {
    /// Link key.
    pub key: [u8; 16],
    /// Key sequence.
    pub key_seq: u8,
    /// 0 provisional, 1 unverified, 2 verified.
    pub attrs: u8,
    /// 0 global, 1 install code, 2 TC generated, 3 imported, 4 hashed.
    pub origin: u8,
    /// Outgoing frame counter.
    pub tx_counter: u32,
    /// Incoming frame counter floor.
    pub rx_floor: u32,
}

/// One device of a backup.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BackupDevice {
    /// IEEE (wire order).
    pub ieee: [u8; 8],
    /// Short address, if valid.
    pub nwk: Option<u16>,
    /// A child of the coordinator.
    pub is_child: bool,
    /// Child info.
    pub child: Option<BackupChild>,
    /// Link key.
    pub link: Option<BackupLinkKey>,
}

/// One item of a coordinator backup: the content of an Open Coordinator
/// Backup file (ZRHP spec 9.1–9.3 records).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BackupItem {
    /// The coordinator node.
    Node {
        /// IEEE (wire order).
        ieee: [u8; 8],
        /// The IEEE is (or should become) an override of the factory one.
        ieee_override: bool,
    },
    /// The network.
    Network {
        /// PAN ID.
        pan_id: u16,
        /// Extended PAN ID (wire order).
        ext_pan_id: [u8; 8],
        /// Channel.
        channel: u8,
        /// Channel mask (bit n = channel n).
        channel_mask: u32,
        /// NWK update ID.
        nwk_update_id: u8,
        /// Network manager.
        nwk_manager: u16,
        /// Security level (5).
        security_level: u8,
        /// TX power (dBm), if known.
        tx_power: Option<i8>,
    },
    /// The network key.
    NetworkKey {
        /// Key.
        key: [u8; 16],
        /// Sequence number.
        seq: u8,
        /// Outgoing frame counter.
        tx_counter: u32,
        /// Active key.
        active: bool,
    },
    /// The Trust Center link key.
    TcLinkKey {
        /// Global TCLK.
        key: [u8; 16],
        /// Trust Center IEEE (wire order).
        tc_ieee: [u8; 8],
        /// Global APS frame counter.
        tx_counter: u32,
        /// Hashed (EZSP) mode active.
        hashed: bool,
    },
    /// The EZSP hashed TCLK seed (`stack_specific.ezsp.hashed_tclk`).
    HashedTclkSeed([u8; 16]),
    /// zigbee-rs NCP parameters (`stack_specific.zigbee_rs`).
    RsParams {
        /// Frame counter reservation stride.
        fc_stride: u32,
        /// Table epoch.
        table_epoch: u32,
        /// NWK durable frame counter limit.
        nwk_fc_limit: u32,
        /// APS durable frame counter limit.
        aps_fc_limit: u32,
        /// Tables are backed by the host.
        host_backed_tables: bool,
    },
    /// One device.
    Device(BackupDevice),
}

/// Receives a backup export, item by item.
pub trait BackupSink {
    /// One item; an error aborts the export.
    fn item(&mut self, item: &BackupItem) -> Result<(), CoordError>;
}

/// Builds a [`RestoreBlob`] for the backend that created the encoder;
/// devices can follow in batches.
pub trait RestoreEncoder: Send {
    /// Appends one item.
    fn push(&mut self, item: &BackupItem) -> Result<(), CoordError>;
    /// The encoded restore data.
    fn finish(self: Box<Self>) -> RestoreBlob;
}

/// Restore data in the encoding of one backend (ZRHP: the record stream
/// without `END`).
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct RestoreBlob(pub Vec<u8>);

/// Restore parameters.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RestoreOptions {
    /// Let the NCP take the backup's coordinator IEEE.
    pub allow_ieee_change: bool,
    /// The operator accepts that the NCP takes the backup's coordinator
    /// IEEE through a token that can be written once only (EZSP
    /// `MFG_CUSTOM_EUI_64`): irreversible. Without it, a backend that has
    /// no rewritable IEEE refuses the restore ([`NetworkAdmin::restore_check`]).
    pub ieee_write_once: bool,
    /// Added to the network-key frame counter.
    pub nwk_margin: u32,
    /// Added to the APS frame counter (2²⁰ when the backup has no TCLK
    /// counter).
    pub aps_margin: u32,
}

impl Default for RestoreOptions {
    fn default() -> Self {
        Self {
            allow_ieee_change: true,
            ieee_write_once: false,
            nwk_margin: 10_000,
            aps_margin: 10_000,
        }
    }
}

/// [`RestoreReport::notes`] codes: 1–4 are the ZRHP `BKP_RESTORE_PUT`
/// notes (spec 9.4), the others are backend notes of the whole restore
/// (item index 0, the coordinator).
pub mod restore_note {
    /// The link key stays with the host (not on the NCP).
    pub const HOST_BACKED: u8 = 1;
    /// A child the NCP's child table had no room for (restored as a
    /// device only).
    pub const CHILD_DEMOTED: u8 = 2;
    /// The item was not restored (e.g. no room in the NCP's key table).
    pub const IGNORED: u8 = 3;
    /// A frame counter floor was raised.
    pub const FLOOR_RAISED: u8 = 4;
    /// The NCP kept its own IEEE (`allow_ieee_change` off): devices know
    /// the trust center by the backup's.
    pub const IEEE_KEPT: u8 = 5;
    /// The backup's IEEE was written to the write-once token.
    pub const IEEE_WRITTEN_ONCE: u8 = 6;
    /// The backup's IEEE was written to a rewritable token.
    pub const IEEE_REWRITTEN: u8 = 7;
    /// The backup has no trust center link key root (another stack's
    /// backup): a new random one was generated.
    pub const TCLK_ROOT_GENERATED: u8 = 8;
    /// The NWK update ID could not be restored (the NCP formed with 0).
    pub const UPDATE_ID_NOT_RESTORED: u8 = 9;
}

/// Outcome of a restore.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct RestoreReport {
    /// First NWK frame counter of the restored network.
    pub nwk_fc_start: u32,
    /// First APS frame counter.
    pub aps_fc_start: u32,
    /// Link keys the NCP caches.
    pub link_keys_on_ncp: u16,
    /// Link keys only the host holds.
    pub link_keys_host_backed: u16,
    /// Children restored into the NCP's child table.
    pub children: u16,
    /// `(item index, backend note)` per restored item with a note.
    pub notes: Vec<(u16, u8)>,
}

/// One firmware slot of the NCP.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct FwSlot {
    /// Slot number.
    pub slot: u8,
    /// 0 empty, 1 running, 2 running trial, 3 staged, 4 inactive.
    pub state: u8,
    /// Image version.
    pub version: u32,
    /// Image SHA-256.
    pub sha256: [u8; 32],
}

/// Description of an NCP firmware image.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct FwImage {
    /// Size in bytes.
    pub size: u32,
    /// SHA-256 of the whole image.
    pub sha256: [u8; 32],
    /// Version (`0xMMmmrrrr`).
    pub version: u32,
    /// Backend image format.
    pub format: u8,
    /// Bit0 allow downgrade.
    pub flags: u8,
}

/// Where image bytes come from; streaming sources only support increasing
/// offsets.
pub trait FwSource: Send {
    /// Reads up to `buf.len()` bytes at `offset`.
    fn read_at(&mut self, offset: u32, buf: &mut [u8]) -> io::Result<usize>;
}

/// Phase of an NCP firmware update.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FwPhase {
    /// Nothing in progress.
    Idle,
    /// Transferring the image.
    Staging {
        /// Bytes acknowledged.
        written: u32,
        /// Image size.
        total: u32,
    },
    /// Activated; waiting for the new image's session.
    Activated {
        /// Expected version.
        version: u32,
    },
    /// The new image runs and was confirmed.
    Confirmed {
        /// Running version.
        version: u32,
    },
    /// The NCP came back with another image (rollback).
    RolledBack {
        /// Version that was activated.
        expected: u32,
        /// Version running now.
        running: u32,
    },
    /// The update failed.
    Failed(String),
}

/// NCP firmware update.
pub trait NcpFirmware: Send + Sync {
    /// The NCP's firmware slots.
    fn slots(&self) -> Result<Vec<FwSlot>, CoordError>;
    /// Checks that `image` can be installed, without transferring it.
    fn preflight(&self, image: &FwImage) -> Result<(), CoordError>;
    /// Transfers and activates `image`; returns the slot it went to.
    fn update(&self, image: &FwImage, src: &mut dyn FwSource) -> Result<u8, CoordError>;
    /// Confirms the running image.
    fn confirm(&self) -> Result<(), CoordError>;
    /// The update in progress, if any.
    fn pending(&self) -> FwPhase;
}

/// Network administration. Implementations may block; callers run them on
/// job threads.
pub trait NetworkAdmin: Send + Sync {
    /// Forms a new network (the NCP must have none).
    fn form(&self, p: FormParams) -> Result<NetworkParams, CoordError> {
        let _ = p;
        Err(CoordError::Unsupported)
    }

    /// Leaves the network and clears it from the NCP.
    fn leave_reset(&self) -> Result<(), CoordError> {
        Err(CoordError::Unsupported)
    }

    /// Energy scan: `exp` per channel is 15.36 ms × (2ⁿ + 1).
    fn energy_scan(&self, mask: u32, exp: u8) -> Result<Vec<EnergyChannel>, CoordError> {
        let _ = (mask, exp);
        Err(CoordError::Unsupported)
    }

    /// Active (beacon) scan.
    fn active_scan(&self, mask: u32, exp: u8) -> Result<Vec<Beacon>, CoordError> {
        let _ = (mask, exp);
        Err(CoordError::Unsupported)
    }

    /// Moves the network to channel `ch`.
    fn change_channel(&self, ch: u8) -> Result<ChannelChange, CoordError> {
        let _ = ch;
        Err(CoordError::Unsupported)
    }

    /// Sets the TX power; returns what the NCP applied (dBm).
    fn set_tx_power(&self, dbm: i8) -> Result<i8, CoordError> {
        let _ = dbm;
        Err(CoordError::Unsupported)
    }

    /// The TX power the operator set, reapplied after NCP restarts.
    fn tx_power_setting(&self) -> Option<i8> {
        None
    }

    /// The coordinator's [`CoordStatus`] snapshot (no I/O, like
    /// [`Coordinator::status`](crate::Coordinator::status)), for the job
    /// threads, which have no `Coordinator`: the network a job acts on,
    /// the NCP a backup names. `None`: not known here.
    fn status(&self) -> Option<CoordStatus> {
        None
    }

    /// Reads the coordinator's neighbor and child tables, and its route
    /// table when `routes`.
    fn coordinator_tables(&self, routes: bool) -> TablesRead {
        TablesRead {
            neighbors: Err(CoordError::Unsupported),
            children: Err(CoordError::Unsupported),
            routes: routes.then_some(Err(CoordError::Unsupported)),
        }
    }

    /// Sends a ZDO request to `nwk` and waits up to `t` for its delivery
    /// and up to `t` for its response. `zdp` is the request's ZDP payload,
    /// starting with the transaction sequence number the caller chose; the
    /// result is the response's payload after its sequence number.
    ///
    /// Errors: [`CoordError::NoAck`] not delivered (the Zigbee status),
    /// [`CoordError::Timeout`] no response; anything else failed to send.
    fn zdo_request(
        &self,
        nwk: u16,
        cluster: u16,
        zdp: &[u8],
        t: Duration,
    ) -> Result<Vec<u8>, CoordError> {
        let _ = (nwk, cluster, zdp, t);
        Err(CoordError::Unsupported)
    }

    /// NCP diagnostics of the counter `groups`, reset after reading when
    /// `reset`.
    fn diagnostics(&self, groups: u8, reset: bool) -> Diagnostics {
        let _ = (groups, reset);
        Diagnostics::default()
    }

    /// Exports the network into `sink`, with keys when `keys`.
    fn backup_export(&self, keys: bool, sink: &mut dyn BackupSink) -> Result<(), CoordError> {
        let _ = (keys, sink);
        Err(CoordError::Unsupported)
    }

    /// An encoder for [`Self::backup_restore`].
    fn restore_encoder(&self) -> Result<Box<dyn RestoreEncoder>, CoordError> {
        Err(CoordError::Unsupported)
    }

    /// Checks, without changing anything, that `blob` can be restored with
    /// `o` (e.g. that the NCP can take the backup's coordinator IEEE): a
    /// refusal here leaves the NCP's network as it is. Default: no check.
    fn restore_check(&self, blob: &RestoreBlob, o: RestoreOptions) -> Result<(), CoordError> {
        let _ = (blob, o);
        Ok(())
    }

    /// Restores a network into the NCP.
    fn backup_restore(
        &self,
        blob: RestoreBlob,
        o: RestoreOptions,
    ) -> Result<RestoreReport, CoordError> {
        let _ = (blob, o);
        Err(CoordError::Unsupported)
    }

    /// NCP firmware update, if the backend supports it.
    fn firmware(&self) -> Option<&dyn NcpFirmware> {
        None
    }
}
